1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	}
66	
67	const ITEM_SPECS = {
68	  sword: { basePremium: 100, insuranceValue: 1000 },
69	  amulet: { basePremium: 60, insuranceValue: 600 },
70	  staff: { basePremium: 80, insuranceValue: 800 },
71	  potion: { basePremium: 40, insuranceValue: 400 },
72	  rune: { basePremium: 25, insuranceValue: 250 },
73	  moonstone: { basePremium: 25, insuranceValue: 250 },
74	} as const satisfies Record<string, ItemSpec>;
75	
76	type KnownItemType = keyof typeof ITEM_SPECS;
77	
78	const isKnownItemType = (type: string): type is KnownItemType =>
79	  type in ITEM_SPECS;
80	
81	// Unknown item types are not yet rejected — the spec requires an error, but no
82	// test drives that behaviour yet, so they carry zeroes for the moment.
83	const UNKNOWN_TYPE_SPEC: ItemSpec = { basePremium: 0, insuranceValue: 0 };
84	
85	const specForItem = (item: Item): ItemSpec =>
86	  isKnownItemType(item.type) ? ITEM_SPECS[item.type] : UNKNOWN_TYPE_SPEC;
87	
88	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
89	
90	const BLOCK_SIZE = 3;
91	
92	const BLOCK_BASE_PREMIUM = 60;
93	
94	const sum = (amounts: number[]): number =>
95	  amounts.reduce((total, amount) => total + amount, 0);
96	
97	// "Alike" means the same exact type, not merely the same family: two runes and
98	// a moonstone are three components but not three alike ones, so grouping them
99	// by type keeps them apart and denies them the block price.
100	const groupByType = (items: Item[]): Item[][] => {
101	  const groups = new Map<string, Item[]>();
102	  for (const item of items) {
103	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
104	  }
105	  return [...groups.values()];
106	};
107	
108	// A block is not carved out of a larger group: the block price applies only
109	// when the group consists of exactly three alike components (7 runes cost
110	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
111	// ever passes a single group from groupByType.
112	const basePremiumForGroup = (group: Item[]): number =>
113	  group.length === BLOCK_SIZE
114	    ? BLOCK_BASE_PREMIUM
115	    : sum(group.map(basePremiumForItem));
116	
117	const basePremiumForItems = (items: Item[]): number =>
118	  sum(groupByType(items).map(basePremiumForGroup));
119	
120	const CURSE_SURCHARGE = 0.5;
121	
122	// Every modifier is an additive percentage of its OWN base — modifiers never
123	// compound with each other. Item-scoped modifiers take the affected item's base
124	// premium as their base; policy-scoped modifiers take the policy base premium
125	// (the sum of all item base premiums). So the total is always
126	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
127	const modifierAmount = (rate: number, base: number): number => rate * base;
128	
129	const ENCHANTMENT_SURCHARGE = 0.3;
130	
131	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
132	
133	const isCursed = (item: Item): boolean => item.cursed === true;
134	
135	const attractsEnchantmentSurcharge = (item: Item): boolean =>
136	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
137	
138	interface ItemModifier {
139	  rate: number;
140	  appliesTo: (item: Item) => boolean;
141	}
142	
143	// Each item-scoped modifier is a row: a rate and the condition under which it
144	// applies. The predicate names the modifier, so a row needs no separate label.
145	// Adding a modifier means adding a row, not a new branch.
146	const ITEM_MODIFIERS: ItemModifier[] = [
147	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
148	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
149	];
150	
151	const itemModifierRates = (item: Item): number[] =>
152	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
153	    (modifier) => modifier.rate,
154	  );
155	
156	const LOYALTY_DISCOUNT = 0.2;
157	
158	const LOYALTY_THRESHOLD_YEARS = 2;
159	
160	const isLongStanding = (customer: Customer): boolean =>
161	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
162	
163	// Discounts are surcharges with the sign flipped: expressing one as a negative
164	// rate lets it flow through the same additive sum as every surcharge, with no
165	// separate subtraction step. Discount constants stay positive magnitudes and
166	// are negated here, at the point of use, so the direction is visible in the
167	// rate list rather than buried in a constant's sign.
168	const asDiscount = (rate: number): number => -rate;
169	
170	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
171	
172	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
173	
174	// Policy-scoped modifiers apply to the policy base premium. Unlike item
175	// modifiers they select on the customer and on the quote's position in the
176	// scenario rather than on an item.
177	//
178	// The initial-assessment surcharge applies to every quote: each item is treated
179	// as a first insurance regardless of customer history. The follow-up discount
180	// is what distinguishes a customer's later contracts.
181	const policyModifierRates = (
182	  customer: Customer,
183	  isFollowUpContract: boolean,
184	): number[] => [
185	  INITIAL_ASSESSMENT_SURCHARGE,
186	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
187	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
188	];
189	
190	const itemModifiersTotal = (items: Item[]): number =>
191	  sum(
192	    items.flatMap((item) =>
193	      itemModifierRates(item).map((rate) =>
194	        modifierAmount(rate, basePremiumForItem(item)),
195	      ),
196	    ),
197	  );
198	
199	const policyModifiersTotal = (
200	  policyBasePremium: number,
201	  customer: Customer,
202	  isFollowUpContract: boolean,
203	): number =>
204	  sum(
205	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
206	      modifierAmount(rate, policyBasePremium),
207	    ),
208	  );
209	
210	// All amounts are rounded to whole G in the MHPCO's favour. For a premium —
211	// money flowing to the MHPCO — its favour is upwards. The payout half of this
212	// rule rounds the other way, but no test drives payouts yet, so only the
213	// premium direction is named here.
214	const roundPremiumInMHPCOsFavour = (amount: number): number =>
215	  Math.ceil(amount);
216	
217	const quotePremium = (
218	  items: Item[],
219	  customer: Customer,
220	  isFollowUpContract: boolean,
221	): number => {
222	  const policyBasePremium = basePremiumForItems(items);
223	  return roundPremiumInMHPCOsFavour(
224	    policyBasePremium +
225	      itemModifiersTotal(items) +
226	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
227	      PROCESSING_FEE,
228	  );
229	};
230	
231	const insuranceValueForItem = (item: Item): number =>
232	  specForItem(item).insuranceValue;
233	
234	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
235	// figure from ITEM_SPECS, but the premium side groups by type first so a block
236	// of three alike components can be priced as one; this side never groups. Three
237	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
238	// discount on the price of cover, not a reduction of the cover bought.
239	//
240	// So the near-symmetry is a false friend: factoring the two into one traversal
241	// would read as tidier and would silently make blocks shrink the insurance sum.
242	// The repetition of `sum(items.map(...))` is the price of keeping them free to
243	// diverge, and is paid on purpose.
244	const insuranceSum = (items: Item[]): number =>
245	  sum(items.map(insuranceValueForItem));
246	
247	const CAP_MULTIPLE = 2;
248	
249	// The cap is twice the insurance sum — the value the items are insured FOR, so
250	// it is computed from the items alone and never from the premium. Curses,
251	// enchantments and loyalty change what a policy costs without changing what it
252	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
253	// separation visible at the one place a policy is created.
254	const capForItems = (items: Item[]): number =>
255	  CAP_MULTIPLE * insuranceSum(items);
256	
257	const DEDUCTIBLE = 100;
258	
259	interface Policy {
260	  items: Item[];
261	  remainingCap: number;
262	}
263	
264	// Steps are not independent: a quote's premium depends on how many quotes came
265	// before it, and a claim draws down the cap of a policy an earlier quote
266	// created. So a step is a function from state to (result, next state), and the
267	// scenario is a fold over that — not a map, which would promise an independence
268	// the steps do not have.
269	//
270	// Policies are keyed by the index of the quote step that created them: a claim
271	// step names its policy by that zero-based index.
272	interface ScenarioState {
273	  quotesSoFar: number;
274	  policies: Map<number, Policy>;
275	}
276	
277	const INITIAL_STATE: ScenarioState = {
278	  quotesSoFar: 0,
279	  policies: new Map(),
280	};
281	
282	interface StepOutcome {
283	  result: StepResult;
284	  state: ScenarioState;
285	}
286	
287	// Both operations end by filing a policy under its quote's index — a claim
288	// re-files the same policy with a drawn-down cap. Naming that once keeps the
289	// Map out of the operations, so neither has to know how policies are stored.
290	const withPolicy = (
291	  state: ScenarioState,
292	  policyIndex: number,
293	  policy: Policy,
294	): ScenarioState => ({
295	  ...state,
296	  policies: new Map(state.policies).set(policyIndex, policy),
297	});
298	
299	const runQuote = (
300	  step: QuoteStep,
301	  customer: Customer,
302	  state: ScenarioState,
303	  stepIndex: number,
304	): StepOutcome => ({
305	  result: {
306	    premium: quotePremium(step.items, customer, state.quotesSoFar > 0),
307	  },
308	  state: withPolicy(
309	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
310	    stepIndex,
311	    {
312	      items: step.items,
313	      remainingCap: capForItems(step.items),
314	    },
315	  ),
316	});
317	
318	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
319	
320	const REDUCED_REIMBURSEMENT_RATE = 0.5;
321	
322	const FULL_REIMBURSEMENT_RATE = 1;
323	
324	// Reads enchantment like the premium-side surcharge rule, but is a different
325	// rule with its own level: this one halves what a claim pays out, that one
326	// raises what a policy costs. Sharing a predicate would tie two levels that the
327	// spec lets move independently, so the shape is repeated deliberately.
328	const qualifiesForReducedReimbursement = (item: Item): boolean =>
329	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
330	
331	// The reimbursement rate is decided first, then one deductible comes off.
332	//
333	// The dragon-material clause is absent on purpose, not by oversight. It promises
334	// full reimbursement of the damage before the deductible — which is exactly what
335	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
336	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
337	// them the two facts leave the clause with no input it can move: dragon material
338	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
339	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
340	// would add a branch no test could ever tell from the default — a distinction
341	// the domain does not make.
342	const reimbursementRate = (item: Item): number =>
343	  qualifiesForReducedReimbursement(item)
344	    ? REDUCED_REIMBURSEMENT_RATE
345	    : FULL_REIMBURSEMENT_RATE;
346	
347	const payoutForDamage = (damage: Damage, item: Item): number =>
348	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
349	
350	// Returns AN insured item of the damaged type, not THE damaged one — a policy
351	// can already cover two swords, so the type does not name a unique item. That
352	// is sound only because the answer is used solely to read the item's payout
353	// attributes, and every damage entry of a type is currently answered with the
354	// same first match. The pending two-swords-damaged test breaks that: two entries
355	// must claim two DISTINCT items, which turns this lookup into a pairing that
356	// consumes what it matches. The honest name marks the spot.
357	//
358	// A damage naming a type the policy does not cover is a spec error case with no
359	// test yet — the assertion stands in until one arrives, at which point the
360	// missing case becomes the error branch.
361	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
362	  policy.items.find((item) => item.type === damage.itemType)!;
363	
364	const payoutForIncident = (policy: Policy, incident: Incident): number =>
365	  sum(
366	    incident.damages.map((damage) =>
367	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
368	    ),
369	  );
370	
371	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
372	  // A claim naming a policy that does not exist is a spec error case, but no
373	  // test drives it yet. The assertion stands in until one does — at which point
374	  // the missing case becomes the error branch rather than a crash.
375	  const policy = state.policies.get(step.policy)!;
376	  const payout = payoutForIncident(policy, step.incident);
377	  const remainingCap = policy.remainingCap - payout;
378	  return {
379	    result: { payout, remainingCap },
380	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
381	  };
382	};
383	
384	// Dispatch decides once what a step is; each operation then owns both its
385	// result and how it advances the state, so no caller has to re-test step.op to
386	// know what the step did.
387	const runStep = (
388	  step: Step,
389	  customer: Customer,
390	  state: ScenarioState,
391	  stepIndex: number,
392	): StepOutcome =>
393	  step.op === "quote"
394	    ? runQuote(step, customer, state, stepIndex)
395	    : runClaim(step, state);
396	
397	// The fold carries both halves of the outcome: the results accumulated so far
398	// and the state the next step will see. Threading the state explicitly (rather
399	// than recovering it from the last result) keeps the dependency between steps
400	// visible in the type.
401	interface ScenarioRun {
402	  results: StepResult[];
403	  state: ScenarioState;
404	}
405	
406	const INITIAL_RUN: ScenarioRun = { results: [], state: INITIAL_STATE };
407	
408	const appendStep =
409	  (customer: Customer) =>
410	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
411	    const outcome = runStep(step, customer, run.state, stepIndex);
412	    return {
413	      results: [...run.results, outcome.result],
414	      state: outcome.state,
415	    };
416	  };
417	
418	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
419	  results: steps.reduce(appendStep(customer), INITIAL_RUN).results,
420	});
421

