183	    it("a sword with exactly enchantment 5 adds a 30 % high-enchantment surcharge", () => {
184	      const result = runScenario({
185	        customer: { yearsWithMHPCO: 0 },
186	        steps: [
187	          {
188	            op: "quote",
189	            items: [{ type: "sword", material: "steel", enchantment: 5 }],
