196	    it("a sword with enchantment 4 gets no high-enchantment surcharge", () => {
197	      const result = runScenario({
198	        customer: { yearsWithMHPCO: 0 },
199	        steps: [
200	          {
201	            op: "quote",
202	            items: [{ type: "sword", material: "steel", enchantment: 4 }],
